#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

// Check if a number is lucky (contains only digits 4 and 7)
bool isLucky(int num) {
    if (num <= 0) return false;
    while (num > 0) {
        int digit = num % 10;
        if (digit != 4 && digit != 7) return false;
        num /= 10;
    }
    return true;
}

// Generate all lucky numbers up to n
vector<int> generateLuckyNumbers(int n) {
    vector<int> lucky;
    for (int i = 1; i <= n; i++) {
        if (isLucky(i)) {
            lucky.push_back(i);
        }
    }
    return lucky;
}

// Factorial calculation with overflow check
// Returns -1 if factorial exceeds 1e9
long long factorial(int n) {
    long long result = 1;
    for (int i = 1; i <= n; i++) {
        result *= i;
        if (result > 1000000000LL) {
            return -1; // Overflow
        }
    }
    return result;
}

