typedef long long ll;

// Check if a number is lucky (contains only 4 and 7)
bool isLucky(ll n) {
    if (n <= 0) return false;
    while (n > 0) {
        int digit = n % 10;
        if (digit != 4 && digit != 7) return false;
        n /= 10;
    }
    return true;
}

// Count lucky numbers up to n
ll countLucky(ll n) {
    if (n <= 0) return 0;
    ll count = 0;
    // Generate all lucky numbers up to n
    // Lucky numbers are formed by digits 4 and 7
    // We can generate them by BFS or DFS
    vector<ll> luckyNums;
    luckyNums.push_back(4);
    luckyNums.push_back(7);
    ll size = 2;
    while (size < luckyNums.size()) {
        ll num = luckyNums[size];
        if (num * 10 + 4 <= n) {
            luckyNums.push_back(num * 10 + 4);
        }
        if (num * 10 + 7 <= n) {
            luckyNums.push_back(num * 10 + 7);
        }
        size++;
    }
    // Count how many are <= n
    for (ll x : luckyNums) {
        if (x <= n) count++;
    }
    return count;
}

// Factorial with cap to avoid overflow
ll factorial(ll n, ll cap) {
    ll result = 1;
    for (ll i = 1; i <= n; i++) {
        result *= i;
        if (result > cap) {
            return cap + 1;
        }
    }
    return result;
}

