// Factorial with cap to avoid overflow
ll factorial(ll n, ll cap) {
    if (n == 0) return 1;
    ll result = 1;
    for (ll i = 1; i <= n; i++) {
        result *= i;
        if (result > cap) return cap + 1; // cap it
    }
    return result;
