typedef long long ll;

// Check if a number is lucky (contains only digits 4 and 7)
bool isLucky(ll num) {
    if (num == 0) return false;
    while (num > 0) {
        int d = num % 10;
        if (d != 4 && d != 7) return false;
        num /= 10;
    }
    return true;
}

// Count how many lucky numbers are <= n
