    queue<ll> q;
    q.push(4);
    q.push(7);
    while (!q.empty()) {
        ll cur = q.front();
        q.pop();
        if (cur > n) continue;
        luckyNums.push_back(cur);
        q.push(cur * 10 + 4);
        q.push(cur * 10 + 7);
    }
    return luckyNums.size();
}

